const input = $input.first().json.body || $input.first().json;
if (!Array.isArray(input.tickets)) throw new Error('tickets must be an array');
const now = input.asOf ? new Date(input.asOf) : new Date();
if (Number.isNaN(now.getTime())) throw new Error('asOf must be a valid date');
const closedStatuses = new Set(['RESOLVED','CLOSED','CANCELLED','REJECTED']);
const tickets = input.tickets.slice(0, 500).map(t => { const due = t.slaDueAt || t.slaDeadline || null; const created = t.createdAt ? new Date(t.createdAt) : null; const deadline = due ? new Date(due) : null; const status = String(t.status || 'OPEN').toUpperCase(); let slaState = 'UNKNOWN'; if (closedStatuses.has(status)) slaState = 'COMPLETED'; else if (deadline && !Number.isNaN(deadline.getTime())) slaState = deadline <= now ? 'BREACHED' : deadline.getTime() - now.getTime() <= 2 * 3600000 ? 'AT_RISK' : 'ON_TRACK'; return { id: t.id ?? null, ticketNumber: t.ticketNumber || null, subject: String(t.subject || t.title || 'Untitled ticket').slice(0, 240), category: t.category || 'GENERAL', priority: t.priority || 'MEDIUM', status, slaDueAt: due, slaState, hoursToDeadline: deadline && !Number.isNaN(deadline.getTime()) ? Math.round((deadline.getTime() - now.getTime()) / 3600000 * 10) / 10 : null, createdAt: t.createdAt || null, location: t.location || null, assignedTo: t.assignedToName || t.assignedTo || null, escalationLevel: Number(t.escalationLevel || 0), isEscalated: Boolean(t.isEscalated) }; });
const counts = { total: tickets.length, breached: tickets.filter(t => t.slaState === 'BREACHED').length, atRisk: tickets.filter(t => t.slaState === 'AT_RISK').length, unassignedOpen: tickets.filter(t => !closedStatuses.has(t.status) && !t.assignedTo).length, emergencyOpen: tickets.filter(t => !closedStatuses.has(t.status) && ['EMERGENCY','CRITICAL'].includes(t.priority)).length };
const prompt = `Prepare a concise helpdesk operations queue review using only supplied records and deterministic SLA states. Do not invent policy, staffing, root causes or outcomes. Sort urgent attention around emergency/critical open tickets, breached SLA and near-deadline tickets. Recommend human review and operational follow-up; do not assign, escalate, close, resolve or message anyone.
As of: ${now.toISOString()}
Counts: ${JSON.stringify(counts)}
Tickets: ${JSON.stringify(tickets)}
Return JSON {"queueSummary":"...","attentionItems":[{"ticketId":"...","reason":"...","suggestedHumanAction":"..."}],"dataGaps":["..."],"humanReviewRequired":true}.`;
return [{ json: { asOf: now.toISOString(), counts, tickets, prompt } }];

const response = $input.first().json;
const source = $('Calculate SLA States').first().json;
let review;
try { review = JSON.parse(response.candidates?.[0]?.content?.parts?.[0]?.text || '{}'); } catch { review = null; }
if (!review || typeof review.queueSummary !== 'string') review = { queueSummary: 'AI summary unavailable. Review breached and at-risk tickets using the computed SLA states.', attentionItems: source.tickets.filter(t => ['BREACHED','AT_RISK'].includes(t.slaState) || (['CRITICAL','EMERGENCY'].includes(t.priority) && !['RESOLVED','CLOSED'].includes(t.status))).map(t => ({ ticketId: t.id, reason: `${t.priority} priority; SLA ${t.slaState}`, suggestedHumanAction: 'Review the ticket and follow the community helpdesk escalation policy.' })), dataGaps: source.tickets.filter(t => t.slaState === 'UNKNOWN').map(t => `No usable SLA deadline for ticket ${t.id}`), humanReviewRequired: true };
review.humanReviewRequired = true;
return [{ json: { status: 'success', asOf: source.asOf, counts: source.counts, review } }];
